class IntSet:
    def __init__(self):
        self.encoding = 16
        self.items = []
    def _fits(self, bits, v):
        return -(2 ** (bits - 1)) <= v <= 2 ** (bits - 1) - 1
    def add(self, v):
        if self._fits(self.encoding, v):
            self.items.append(v); self.items.sort(); return False
        self.encoding = 32 if self._fits(32, v) else 64
        self.items.append(v); self.items.sort(); return True

s = IntSet()
for v in [1, 2, 300]:
    up = s.add(v)
    print("add %-6s encoding=%d upgraded=%s items=%s" % (v, s.encoding, up, s.items))
up = s.add(40000)   # 超过 int16 上限 -> 升级
print("add %-6s encoding=%d upgraded=%s items=%s" % (40000, s.encoding, up, s.items))
